const planets=[
 ['Mercury',88,1407.6,.387,'#b9aaa0',4,'THE SWIFTEST PLANET','A rocky, cratered world that races around the Sun faster than any other planet.'],
 ['Venus',224.7,-5832.5,.723,'#d9bb83',7,'OUR NEIGHBOURING WORLD','Wrapped in thick clouds, Venus spins slowly in the opposite direction to most planets.'],
 ['Earth',365.256,23.9345,1,'#66a9cb',8,'OUR HOME PLANET','An ocean world with a life-filled surface. Our small blue home in the vastness of space.'],
 ['Mars',686.98,24.6229,1.524,'#d77d59',6,'THE RED PLANET','A dusty desert world with towering volcanoes, ancient riverbeds and two tiny moons.'],
 ['Jupiter',4332.59,9.925,5.203,'#d3b18b',20,'KING OF THE PLANETS','A giant of swirling clouds. Jupiter has the fastest rotation of all eight planets.'],
 ['Saturn',10759.22,10.656,9.537,'#d8c393',17,'THE RINGED WORLD','An airy gas giant surrounded by magnificent rings of ice and rocky fragments.'],
 ['Uranus',30688.5,-17.24,19.19,'#9dd9d9',12,'THE TILTED ICE GIANT','A cool blue-green giant with an extreme axial tilt and a retrograde rotation.'],
 ['Neptune',60182,16.11,30.07,'#5c83dc',12,'BEYOND THE BLUE','Dark, cold and swept by fierce winds, Neptune traces the outermost planetary orbit.']
].map((p,i)=>({name:p[0],period:p[1],rotation:p[2],au:p[3],color:p[4],r:p[5],type:p[6],description:p[7],phase:[2.6,4.5,1.2,3.6,5.6,2.2,.3,4][i]}));
const $=id=>document.getElementById(id);let selected=2,paused=false,rotation=0,changeTimer;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;paused=reduced;
const textureNames=['mercury','venus_surface','earth','mars','jupiter','saturn','uranus','neptune'];const worlds=[],textures=[];
function paint(i,angle=0){const c=worlds[i],ctx=c.getContext('2d'),N=500,r=i===5?135:174,cx=250,cy=250;ctx.clearRect(0,0,N,N);const tex=textures[i];if(!tex)return;const img=ctx.createImageData(r*2,r*2),out=img.data;
 for(let y=0;y<r*2;y++)for(let x=0;x<r*2;x++){const nx=(x-r)/r,ny=(y-r)/r,d=nx*nx+ny*ny;if(d>1)continue;const nz=Math.sqrt(1-d);const u=((Math.atan2(nx,nz)/(2*Math.PI)+.5+angle)%1+1)%1;const v=Math.acos(-ny)/Math.PI;let tx=Math.floor(u*tex.width),ty=Math.min(tex.height-1,Math.floor(v*tex.height));const src=(ty*tex.width+tx)*4,k=(y*r*2+x)*4;const light=Math.max(0,-nx*.65-ny*.26+nz*.65);const shade=.025+.975*Math.pow(light,.8);for(let ch=0;ch<3;ch++)out[k+ch]=tex.data[src+ch]*shade;out[k+3]=Math.min(255,(1-d)*r*255);}
 if(i===5){ctx.save();ctx.translate(cx,cy);ctx.rotate(-.35);for(let n=0;n<65;n++){ctx.beginPath();ctx.ellipse(0,0,r*(1.38+n*.009),r*(.40+n*.0026),0,0,Math.PI*2);ctx.strokeStyle=`rgba(192,174,135,${n>38&&n<43?.08:.25+(n%4)*.1})`;ctx.lineWidth=2;ctx.stroke()}ctx.restore()}
 ctx.putImageData(img,cx-r,cy-r); // Composite disc without erasing the transparent ring area.
 if(i===5){const tmp=document.createElement('canvas');tmp.width=tmp.height=500;const t=tmp.getContext('2d');t.putImageData(img,cx-r,cy-r);ctx.clearRect(0,0,500,500);ctx.save();ctx.translate(cx,cy);ctx.rotate(-.35);for(let n=0;n<65;n++){ctx.beginPath();ctx.ellipse(0,0,r*(1.38+n*.009),r*(.40+n*.0026),0,Math.PI,2*Math.PI);ctx.strokeStyle=`rgba(192,174,135,${n>38&&n<43?.06:.5})`;ctx.lineWidth=2;ctx.stroke()}ctx.restore();ctx.drawImage(tmp,0,0);ctx.save();ctx.translate(cx,cy);ctx.rotate(-.35);for(let n=0;n<65;n++){ctx.beginPath();ctx.ellipse(0,0,r*(1.38+n*.009),r*(.40+n*.0026),0,0,Math.PI);ctx.strokeStyle=`rgba(192,174,135,${n>38&&n<43?.06:.5})`;ctx.lineWidth=2;ctx.stroke()}ctx.restore()}
 if(i===2||i===7){ctx.beginPath();ctx.arc(cx,cy,r+.6,0,7);ctx.strokeStyle=i===2?'#7dbdff55':'#6197ea33';ctx.lineWidth=2;ctx.stroke()}
}
planets.forEach((p,i)=>{let world=document.createElement('button');world.className='world';world.setAttribute('aria-label','Explore '+p.name);world.innerHTML=`<canvas width="500" height="500" role="img" aria-label="${p.name}"></canvas><span class="planet-label">${p.name}</span>`;world.onclick=()=>select(i);$('track').appendChild(world);worlds.push(world.querySelector('canvas'));const b=document.createElement('button');b.innerHTML=`<span class="dot" style="--color:${p.color}"></span>${p.name}`;b.onclick=()=>select(i);$('planets').appendChild(b);
 const image=new Image();image.onload=()=>{const t=document.createElement('canvas');t.width=1024;t.height=512;const ctx=t.getContext('2d');ctx.drawImage(image,0,0,1024,512);textures[i]=ctx.getImageData(0,0,1024,512);paint(i)};image.onerror=()=>{const t=document.createElement('canvas');t.width=256;t.height=128;const ctx=t.getContext('2d');ctx.fillStyle=p.color;ctx.fillRect(0,0,256,128);textures[i]=ctx.getImageData(0,0,256,128);paint(i)};image.src='assets/'+textureNames[i]+'.jpg';});
function align(){const width=parseFloat(getComputedStyle($('track').children[0]).width);$('track').style.transform=`translateX(${-width*(selected+.5)}px)`}
function details(){const p=planets[selected];$('number').textContent=String(selected+1).padStart(2,'0');$('name').textContent=p.name;$('type').textContent=p.type;$('description').textContent=p.description;$('orbit').innerHTML=(p.period>1000?(p.period/365.256).toFixed(1):p.period.toLocaleString())+'<small>'+(p.period>1000?'Earth years':'Earth days')+'</small>';$('rotation').innerHTML=Math.abs(p.rotation).toLocaleString()+'<small>hours'+(p.rotation<0?' · retrograde':'')+'</small>';$('distance').innerHTML=p.au+'<small>AU</small>';$('position').textContent=String(selected+1).padStart(2,'0')+' — '+p.name.toUpperCase();document.querySelector('.information').classList.remove('changing')}
function select(i,initial=false){if(i<0||i>7)return;selected=i;[...$('track').children].forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-pressed',i===j)});[...$('planets').children].forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-current',i===j?'true':'false')});$('previous').disabled=i===0;$('next').disabled=i===7;align();clearTimeout(changeTimer);if(initial||reduced)details();else{document.querySelector('.information').classList.add('changing');changeTimer=setTimeout(details,190)}}
$('previous').onclick=()=>select(selected-1);$('next').onclick=()=>select(selected+1);document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea'))return;if(e.key==='ArrowLeft'){e.preventDefault();select(selected-1)}if(e.key==='ArrowRight'){e.preventDefault();select(selected+1)}});let touchX;document.querySelector('.gallery').addEventListener('touchstart',e=>touchX=e.changedTouches[0].clientX,{passive:true});document.querySelector('.gallery').addEventListener('touchend',e=>{let dx=e.changedTouches[0].clientX-touchX;if(Math.abs(dx)>45)select(selected+(dx<0?1:-1))},{passive:true});$('pause').textContent=paused?'Resume rotation':'Pause rotation';$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'Resume rotation':'Pause rotation'};select(2,true);
setInterval(()=>{if(!paused&&!document.hidden){rotation+=.0003;paint(selected,rotation)}},160);
function stars(){const c=$('stars'),d=Math.min(devicePixelRatio,2);c.width=innerWidth*d;c.height=innerHeight*d;const ctx=c.getContext('2d');ctx.scale(d,d);let seed=17;const rand=()=>{seed=(seed*16807)%2147483647;return seed/2147483647};for(let i=0;i<280;i++){ctx.fillStyle=`rgba(167,190,216,${.1+rand()*.4})`;ctx.beginPath();ctx.arc(rand()*innerWidth,rand()*innerHeight,rand()*.7+.2,0,7);ctx.fill()}align()}addEventListener('resize',stars);stars();
